<main class="content container-fluid"><div class="page-toolbar"><a class="btn btn-outline-secondary" href="<?=url($resource['type']==='test'?'/admin/tests':'/admin/tabuladores')?>">← Volver al módulo</a><a class="btn btn-brand" href="<?=url('/admin/recursos/formulario?id='.$resource['id'])?>">Editar recurso</a></div><section class="card panel-card record-card mx-auto"><div class="card-body p-4 p-lg-5"><div class="d-flex flex-column flex-md-row align-items-md-center gap-3 pb-4 border-bottom"><span class="resource-icon resource-icon-lg"><?=$resource['type']==='test'?'✓':'▦'?></span><div class="flex-grow-1"><span class="eyebrow"><?=e(strtoupper($resource['type']))?></span><h2 class="mt-2 mb-1"><?=e($resource['name'])?></h2><p class="text-secondary mb-0"><?=e($resource['description']?:'Sin descripción')?></p></div><span class="badge rounded-pill fs-6 <?=$resource['active']?'text-bg-success':'text-bg-secondary'?>"><?=$resource['active']?'Publicado':'Inactivo'?></span></div><div class="row g-3 py-4"><?php foreach([['Asignatura',$resource['subject']??'Todas'],['Grupo',$resource['group_name']??'Sin grupo'],['Subgrupo',$resource['subgroup_name']??'Sin subgrupo'],['Archivo',$resource['file_path']??'Sin archivo'],['Creado',$resource['created_at']]] as $d):?><div class="col-md-6 col-xl-4"><div class="detail-box"><span><?=e($d[0])?></span><strong><?=e($d[1])?></strong></div></div><?php endforeach;?><div class="col-md-6 col-xl-4"><div class="detail-box"><span>Enlace externo</span><strong><?php if($resource['external_link']):?><a class="brand-link" href="<?=e($resource['external_link'])?>" target="_blank" rel="noopener">Abrir enlace ↗</a><?php else:?>Sin enlace<?php endif;?></strong></div></div></div><form class="danger-zone" method="post" action="<?=url('/admin/recursos/eliminar')?>" onsubmit="return confirm('¿Eliminar definitivamente este recurso?')"><?=csrf_field()?><input type="hidden" name="id" value="<?=$resource['id']?>"><input type="hidden" name="type" value="<?=$resource['type']?>"><div><strong>Eliminar recurso</strong><p class="mb-0 text-secondary">Esta acción elimina el registro del sistema.</p></div><button class="btn btn-outline-danger">Eliminar recurso</button></form></div></section></main>
